  <GridLayout rows="auto, auto, auto">
    <Label
      row="0"
      text="Option 1"
      class="option-text"
      @tap="$emit('selectedOption', 1)"
    />
    <Label
      row="1"
      text="Option 2"
      class="option-text"
      @tap="$emit('selectedOption', 2)"
    />
    <Label
      row="2"
      text="Option 3"
      class="option-text"
      @tap="$emit('selectedOption', 3)"
