class MainActivity : AppCompatActivity() {

    private lateinit var playerView: PlayerView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        playerView = findViewById(R.id.player_view) as PlayerView

        // Request cookies
        requestCookies { cookie, keyPairId ->
            initPlayer(cookie, keyPairId)
        }
    }

    private fun initPlayer(cookie: String, keyPairId: String) {
        val controller: PlayerController = playerView.playerController

        val urlString = "https://media.elottdev.pp.ua/Rootd4ae5870-2996-4476-8ada-adf487a0ab71/elott-web/Arnold%20War%20in%20UA/manifests/master_manifest.m3u8"

