            val client = OkHttpClient()
            val request = Request.Builder()
                .url("https://yourapiurl.com/api/MediaStorage/GetCookies")
                .build()

            try {
                val response = client.newCall(request).execute()
                response.use { res ->
                    if (res.isSuccessful) {
                        val cookie = res.header("Set-Cookie") ?: ""
                        val keyPairId = res.header("Key-Pair-Id") ?: ""

                        withContext(Dispatchers.Main) {
                            onSuccess(cookie, keyPairId)
                        }
                    } else {
                        Log.e("MainActivity", "Error requesting cookies: ${res.code}")
                    }
