Java is an object-oriented programming language that provides several data structures, including the AVL tree. The AVL tree is a self-balancing binary search tree that maintains the Bounded Tree Height Property, which helps to ensure an efficient search algorithm. Here is a sample snippet of code that demonstrates how to perform rotations in an AVL tree in Java:

```java
class AVLTreeNode {
    private String key;
    private String value;
    private AVLTreeNode left;
    private AVLTreeNode right;
    private int height;

    public AVLTreeNode(String key, String value, AVLTreeNode left, AVLTreeNode right) {
     this.key = key;
     this.value = value;
     this.left = left;
     this.right = right;
     this.height = getHeight();
    }

    public void insert(String key, String value) {
     if (key.equals(this.key)) {
       this.value = value;
     } else if (key.compareTo(this.key) < 0) {
       if (left == null) {
         left = new  AVLTreeNode(key, value, null, null);
       } else {
         left.insert(key, value);
       }
     } else {
       if (right == null) {
         right = new AVLTreeNode(key, value, null, null);
       } else {
         right.insert(key, value);
       }
     }
     this.adjust(getHeight());
     AVL.printTree(this);
    }

    public String search(String searchKey) {
     if (searchKey.equals(this.key))
     return this.value;
     if (searchKey.compareTo(this.key) < 0)
     return (left == null)? null : left.search(searchKey);
     return (right == null)? null : right.search(searchKey);
    }

    private int getHeight() {
      return Math.max(1 + Math.max(left.getHeight(), right.getHeight()));
    }

    private void adjust(int height) {
      if (Math.abs(left.getHeight() - right.getHeight()) > 1) {
       if (right.getHeight() > left.getHeight()) {
          this.left = rotateLeft(this).left;
          this.right = rotateRight(this.left.right);
       } else {
          this.right = rotateRight(this.right);
          this.left = rotateLeft(this.left);
       }
       this.adjust(getHeight());
      }
    }

    private AVLTreeNode rotateLeft(AVLTreeNode u) {
     AVLTreeNode l = u.left;
     u.left = l.right;
     l.right = u;
     l.adjust(l.getHeight());
     u.adjust(this.getHeight() - 1);
     return l;
    }

    private AVLTreeNode rotateRight(AVLTreeNode u) {
     AVLTreeNode r = u.right;
     u.right = r.left;
     r.left = u;
     r.adjust(r.getHeight());
     u.adjust(this.getHeight() - 1);
     return r;
    }
}
```

