from collections import Counter

def clean_input(text: str) -> str:
    text = text.lower()
    return ''.join(c for c in text if c.isalpha())

def type_of_anagram(word1: str, word2: str) -> str:
    counter1, counter2 = Counter(word1), Counter(word2)

    if counter1 == counter2:
        return 'standard'
    elif all(v <= counter2[k] for k, v in counter1.items()):
        return 'subset'
    elif all(v >= counter2[k] for k, v in counter1.items()):
        return 'repeated'
    else:
        return None

def detect_and_classify_anagrams(input_phrases):
    cleaned_inputs = [clean_input(phrase) for phrase in input_phrases]

    standard_anagrams, subset_anagrams, anagrams_with_repetition = {}, {}, {}

    for i in range(len(cleaned_inputs)):
        for j in range(i + 1, len(cleaned_inputs)):
            anagram_type = type_of_anagram(cleaned_inputs[i], cleaned_inputs[j])

            if anagram_type == 'standard':
                standard_anagrams.setdefault(input_phrases[i], []).append(input_phrases[j])
            elif anagram_type == 'subset':
                subset_anagrams.setdefault(input_phrases[i], []).append(input_phrases[j])
            elif anagram_type == 'repeated':
                anagrams_with_repetition.setdefault(input_phrases[i], []).append(input_phrases[j])

