Aquí tienes un ejemplo de código en Java para crear una conexión WebSocket en Android:

    package com.example.app;

    import android.os.Bundle;
    import android.util.Log;
    import android.widget.TextView;

    import androidx.appcompat.app.AppCompatActivity;

    import org.springframework.web.socket.TextMessage;
    import org.springframework.web.socket.WebSocketSession;
    import org.springframework.web.socket.client.WebSocketClient;
    import org.springframework.web.socket.client.standard.StandardWebSocketClient;
    import org.springframework.web.socket.sockjs.client.SockJsClient;
    import org.springframework.web.socket.sockjs.client.Transport;
    import org.springframework.web.socket.sockjs.client.WebSocketTransport;

    import java.net.URI;

    public class MainActivity extends AppCompatActivity {

        private static final String TAG = "MainActivity";
        private static final String SERVER_URL = "http://127.0.0.1:8080/mycontroller";
        private static final String CHANNEL_NAME = "/topic/chat";

        private WebSocketSession session;
        private TextView messageView;

        @Override
        protected void onCreate(Bundle savedInstanceState) {
            super.onCreate(savedInstanceState);
            setContentView(R.layout.activity_main);

            messageView = findViewById(R.id.messageView);

            // Crear el cliente de WebSocket usando SockJsClient y WebSocketTransport
            SockJsClient sockJsClient = new SockJsClient(new WebSocketTransport(new StandardWebSocketClient()));

            // Conectar al servidor usando el método connect y manejar la conexión
            sockJsClient.connect(SERVER_URL, new WebSocketClient.ConnectionCallback() {
                @Override
                public void onOpen(WebSocketSession session) {
                    Log.d(TAG, "Conexión establecida");
                    MainActivity.this.session = session;
                    sendMessage("Conexión establecida");
                }

                @Override
                public void onError(Throwable t) {
                    Log.e(TAG, "Error al conectar: ", t);
                    t.printStackTrace();
                    disconnect();
                }
            });
        }

        private void disconnect() {
            if (session!= null) {
                session.close();
                messageView.setText("Cerrando conexión");
            }
        }

        private void sendMessage(String message) {
            if (session!= null) {
                session.sendMessage(new TextMessage(message));
                messageView.setText(message);
            }
        }
    }

Este código crea una instancia de SockJsClient y utiliza WebSocketTransport para crear un cliente de WebSocket. Luego, usa el método connect para conectar al servidor en el puerto 8080 escuchando la ruta /mycontroller. Cuando se establece la conexión, se llama al método onOpen, y se puede comenzar a enviar y recibir mensajes utilizando los métodos send y receive de la clase WebSocketSession.

