```python
class PriorityStack:
    def __init__(self):
        self.stack = []

    def push(self, item, priority):
        self.stack.append((item, priority))

    def pop(self):
        if len(self.stack) == 0:
            return None
        highest_priority = self.stack[0][1]
        highest_priority_index = 0
        for i in range(1, len(self.stack)):
            if self.stack[i][1] > highest_priority:
                highest_priority = self.stack[i][1]
                highest_priority_index = i

        item = self.stack[highest_priority_index][0]
        del self.stack[highest_priority_index]
        return item

    def display(self):
        if len(self.stack) == 0:
            print("Empty stack")
        else:
            print("Stack with priorities:")
            for item, priority in self.stack:
                print(f"Item: {item}, Priority: {priority}")


