        const questions = [
            {
                question: "What is the capital of France?",
                answers: ["Berlin", "Paris", "Rome"],
                correctAnswer: 1,
            },
            {
                question: "Which language is primarily used for web development?",
                answers: ["Python", "JavaScript", "Java"],
                correctAnswer: 1,
            },
            // Add more questions here...
        ];

        let currentQuestion = 0;

        function showQuestion() {
            const q = questions[currentQuestion];
            document.getElementById("question").innerText = q.question;
            for (let i = 0; i < q.answers.length; i++) {
                document.getElementsByTagName("button")[i].innerText = q.answers[i];
            }
        }

        function submitAnswer(answer) {
            if (answer === questions[currentQuestion].correctAnswer) {
                showMessage("Correct! Good job.");
            } else {
                showMessage("Incorrect. Try again!");
            }
            currentQuestion++;
            if (currentQuestion === questions.length) {
                showMessage("Quiz completed! Good job.");
                document.getElementById("quiz-container").classList.add("hidden");
            } else {
                showQuestion();
            }
        }

        function showMessage(message) {
            document.getElementById("result-message").classList.remove("hidden");
            document.getElementById("result-message").innerText = message;
