function isScreamingSnakeCase(name) {
  return name === name.toUpperCase() && /^[A-Z_]+$/.test(name);
}

module.exports = {
  rules: {
    "screaming-snake-case": {
      create: function (context) {
        return {
          Identifier: function (node) {
            if (!isScreamingSnakeCase(node.name)) {
              context.report({
                node,
                message: `Identifier '${node.name}' should be in SCREAMING_SNAKE_CASE.`,
              });
            }
          },
        };
      },
    },
  },
};
