func readCSVData() -> [(x: Double, y: Double)] {
    guard let fileURL = Bundle.main.url(forResource: "sales_data", withExtension: "csv") else { return [] }
    guard let dataString = try? String(contentsOf: fileURL, encoding: .utf8) else { return [] }

