func performLinearRegression(data: [(x: Double, y: Double)]) -> (slope: Double, intercept: Double) {
    let n = data.count
    let sumX = data.map({ $0.x }).reduce(0, +)
    let sumY = data.map({ $0.y }).reduce(0, +)
    let sumXY = data.map({ $0.x * $0.y }).reduce(0, +)
    let sumXX = data.map({ $0.x * $0.x }).reduce(0, +)

    let slope = (Double(n) * sumXY - sumX * sumY) / (Double(n) * sumXX - sumX * sumX)
    let intercept = (sumY - slope * sumX) / Double(n)

    return (slope: slope, intercept: intercept)
}
```

